INSERT INTO audit_findings (id, ref, book_order, chapter, verse, layer, kind, priority, is_sample, msg, ks_text, foi_text, u68_text, extra_json, in_errata, active, updated_at) VALUES ('c7ca27b40aaa', 'Post 47,4', 1, 47, 4, 'tekst', 'ks_u_manjini', 1, 0, 'FOI i U68 se slažu, KS-online se razlikuje', 'Došli smo da potražimo kratak boravak u ovoj zemlji«, rekoše faraonu, »jer je nestalo paše za stada tvojih slugu, strašna glad pritište kanaansku zemlju. Dopusti da se tvoje sluge nastane u gošenskom kraju.« Faraon reče Josipu: »Neka se, dakle, nastane u gošenskom kraju. A ako znaš da među njima ima prikladnih, postavi ih za nadglednike moga osobnog blaga.« Tako, kad Jakov i njegovi sinovi stigoše u Egipat i kad faraon, kralj egipatski, to ču, reče Josipu: »Budući da su tvoj otac i tvoja braća došli k tebi, egipatska ti je zemlja na raspolaganju: smjesti svoga oca i svoju braću u najboljem kraju.«', 'Došli smo da potražimo kratak boravak u ovoj zemlji«, rekoše faraonu, »jer je nestalo paše za stada tvojih slugu, strašna glad pritište kanaansku zemlju. Dopusti da se tvoje sluge nastane u gošenskom kraju.«', '', '{"diff": [["delete", "faraon rece josipu neka se dakle nastane u gosenskom kraju a ako znas da među njima ima prikladnih postavi ih za nadglednike moga osobnog blaga tako kad jakov i njegovi sinovi stigose u egipat i kad faraon kralj egipatski to cu rece josipu buduci da su tvoj otac i tvoja braca dosli k tebi egipatska ti je zemlja na raspolaganju smjesti svoga oca i svoju bracu u najboljem kraju", ""]]}', 0, 1, '2026-11-04T08:22:59+00:00') ON CONFLICT(id) DO UPDATE SET ref = excluded.ref, book_order = excluded.book_order, chapter = excluded.chapter, verse = excluded.verse, layer = excluded.layer, kind = excluded.kind, priority = excluded.priority, is_sample = excluded.is_sample, msg = excluded.msg, ks_text = excluded.ks_text, foi_text = excluded.foi_text, u68_text = excluded.u68_text, extra_json = excluded.extra_json, in_errata = excluded.in_errata, active = exc