INSERT INTO audit_findings (id, ref, book_order, chapter, verse, layer, kind, priority, is_sample, msg, ks_text, foi_text, u68_text, extra_json, in_errata, active, updated_at) VALUES ('aa613ac0ecd3', '1 Sam 3,21', 9, 3, 21, 'tekst', 'ks_razlicit_od_foi', 2, 0, 'KS-online i FOI se razlikuju (U68 je treći, starije izdanje)', 'Jahve se i dalje javljao u Šilu, jer se objavljivao Samuelu,', 'Jahve se i dalje javljao u Šilu, jer se objavljivao Samuelu, [4] i riječ se Samuelova obraćala svemu Izraelu. (Eli je bio vrlo star, a njegovi su sinovi ustrajali u svome opakom postupku pred Jahvom.)', 'Jahve se i dalje javljao u Šilu, jer se objavljivao Samuelu, [4:1] i riječ se Samuelova obraćala svemu Izraelu. (Eli je bio vrlo star, a njegovi su sinovi ustrajali u svome opakom postupku pred Jahvom.)', '{"diff": [["insert", "", "4 i rijec se samuelova obracala svemu izraelu eli je bio vrlo star a njegovi su sinovi ustrajali u svome opakom postupku pred jahvom"]]}', 0, 1, '2026-11-04T08:22:59+00:00') ON CONFLICT(id) DO UPDATE SET ref = excluded.ref, book_order = excluded.book_order, chapter = excluded.chapter, verse = excluded.verse, layer = excluded.layer, kind = excluded.kind, priority = excluded.priority, is_sample = excluded.is_sample, msg = excluded.msg, ks_text = excluded.ks_text, foi_text = excluded.foi_text, u68_text = excluded.u68_text, extra_json = excluded.extra_json, in_errata = excluded.in_errata, active = excluded.active, updated_at = excluded.updated_at;
INSERT INTO audit_findings (id, ref, book_order, chapter, verse, layer, kind, priority, is_sample, msg, ks_text, foi_text, u68_text, extra_json, in_errata, active, updated_at) VALUES ('3cbd31563479', '1 Kr 5,7', 11, 5, 7, 'poravnanje', 'krivi_broj', 2, 0, 'tekst odgovara retku 1 Kr 5,1 u U68 (100 %), a istom broju samo 45 %', 'Salomon je proširio svoju vlast nad svim kraljevstvima od Rijeke sve do zemlje filistejske i do međe egipatske. Ona su donosila svoj danak i služila Salomonu sve dane njegova života.', '', '', '{"suggested": "1 Kr 5,1"}', 0, 1, '2026-11-04T08:22:59+00:00') ON CONFLICT(id) DO UPDATE SET ref = excluded.ref, book_order = excluded.book_order, chapter = excluded.chapter, verse = excluded.verse, layer = excluded.layer, kind = excluded.kind, priority = excluded.priority, is_sample = excluded.is_sample, msg = excluded.msg, ks_text = excluded.ks_text, foi_text = excluded.foi_text, u68_text = excluded.u68_text, extra_json = excluded.extra_json, in_errata = excluded.in_errata, active = excluded.active, updated_at = excluded.updated_at;
