INSERT INTO audit_findings (id, ref, book_order, chapter, verse, layer, kind, priority, is_sample, msg, ks_text, foi_text, u68_text, extra_json, in_errata, active, updated_at) VALUES ('98b7c74993e3', '1 Kr 8,9', 11, 8, 9, 'tekst', 'ks_razlicit_od_foi', 2, 0, 'KS-online i FOI se razlikuju (U68 je treći, starije izdanje)', 'U Kovčegu nije bilo ništa, osim dviju kamenih ploča koje metnu Mojsije na Horebu, gdje Jahve sklopi savez s Izraelcima pošto iziđoše iz Egipta. Ondje su ostale do danas.', 'U Kovčegu nije bilo ništa, osim dviju kamenih ploča koje metnu Mojsije na Horebu, gdje Jahve sklopi savez s Izraelcima pošto iziđoše iz Egipta.', 'U Kovčegu nije bilo ništa, osim dviju kamenih ploča koje metnu Mojsije na Horebu, gdje Jahve sklopi Savez s Izraelcima pošto iziđoše iz Egipta. [8b] Ondje su ostale do danas.', '{"diff": [["delete", "ondje su ostale do danas", ""]]}', 0, 1, '2026-11-04T08:22:59+00:00') ON CONFLICT(id) DO UPDATE SET ref = excluded.ref, book_order = excluded.book_order, chapter = excluded.chapter, verse = excluded.verse, layer = excluded.layer, kind = excluded.kind, priority = excluded.priority, is_sample = excluded.is_sample, msg = excluded.msg, ks_text = excluded.ks_text, foi_text = excluded.foi_text, u68_text = excluded.u68_text, extra_json = excluded.extra_json, in_errata = excluded.in_errata, active = excluded.active, updated_at = excluded.updated_at;
INSERT INTO audit_findings (id, ref, book_order, chapter, verse, layer, kind, priority, is_sample, msg, ks_text, foi_text, u68_text, extra_json, in_errata, active, updated_at) VALUES ('c25d0a624566', '1 Kr 11,22', 11, 11, 22, 'tekst', 'ks_razlicit_od_foi', 2, 0, 'KS-online i FOI se razlikuju (U68 je treći, starije izdanje)', 'Faraon mu reče: »Što ti nedostaje u mene te želiš poći u svoju zemlju?« A on mu odgovori: »Ništa, ali me pusti da odem!« To je bilo zlo što ga je učinio Hadad: mrzio je Izraela i vladao je Edomom.', 'Faraon mu reče: »Što ti nedostaje u mene te želiš poći u svoju zemlju?« A on mu odgovori: »Ništa, ali me pusti da odem!«', 'Faraon mu reče: “Što ti nedostaje u mene te želiš poći u svoju zemlju?” A on mu odgovori: “Ništa, ali me pusti da odem!” [25b] To je bilo zlo što ga je učinio Hadad: mrzio je Izraela i vladao je Edomom.', '{"diff": [["delete", "to je bilo zlo sto ga je ucinio hadad mrzio je izraela i vladao je edomom", ""]]}', 0, 1, '2026-11-04T08:22:59+00:00') ON CONFLICT(id) DO UPDATE SET ref = excluded.ref, book_order = excluded.book_order, chapter = excluded.chapter, verse = excluded.verse, layer = excluded.layer, kind = excluded.kind, priority = excluded.priority, is_sample = excluded.is_sample, msg = excluded.msg, ks_text = excluded.ks_text, foi_text = excluded.foi_text, u68_text = excluded.u68_text, extra_json = excluded.extra_json, in_errata = excluded.in_errata, active = excluded.active, updated_at = excluded.updated_at;
INSERT INTO audit_findings (id, ref, book_order, chapter, verse, layer, kind, priority, is_sample, msg, ks_text, foi_text, u68_text, extra_json, in_errata, active, updated_at) VALUES ('687d00067365', '2 Kr 19,9', 12, 19, 9, 'tekst', 'ks_razlicit_od_foi', 2, 0, 'KS-online i FOI se razlikuju (U68 je treći, starije izdanje)', 'Dočuo je, naime, vijest o Tirhaku, kralju etiopskome: »Evo, izašao je da se bori protiv tebe.« Tada Sanherib ponovno uputi poslanike da kažu Ezekiji:', 'Dočuo je, naime, vijest o Tirhaku, kralju etiopskome: »Evo, izašao je da se bori protiv tebe.«', 'Dočuo je, naime, vijest o Tirhaku, kralju etiopskome: “Evo, izašao je da se bori protiv tebe.” Tada Sanherib ponovo uputi poslanike da kažu Ezekiji:', '{"diff": [["delete", "tada sanherib ponovno uputi poslanike da kazu ezekiji", ""]]}', 0, 1, '2026-11-04T08:22:59+00:00') ON CONFLICT(id) DO UPDATE SET ref = excluded.ref, book_order = excluded.book_order, chapter = excluded.chapter, verse = excluded.verse, layer = excluded.layer, kind = excluded.kind, priority = excluded.priority, is_sample = excluded.is_sample, msg = excluded.msg, ks_text = excluded.ks_text, foi_text = excluded.foi_text, u68_text = excluded.u68_text, extra_json = excluded.extra_json, in_errata = excluded.in_errata, active = excluded.active, updated_at = excluded.updated_at;
INSERT INTO audit_findings (id, ref, book_order, chapter, verse, layer, kind, priority, is_sample, msg, ks_text, foi_text, u68_text, extra_json, in_errata, active, updated_at) VALUES ('54185586c359', '1 Ljet 8,40', 13, 8, 40, 'tekst', 'ks_razlicit_od_foi', 2, 0, 'KS-online i FOI se razlikuju (U68 je treći, starije izdanje)', 'Ulamovi su sinovi bili hrabri junaci koji su zapinjali lûk i imali mnogo sinova i unuka, sto pedeset. Svi su oni bili od Benjaminovih si-nova.', 'Ulamovi su sinovi bili hrabri junaci koji su zapinjali l?k i imali mnogo sinova i unuka, sto pedeset. Svi su oni bili od Benjaminovih sinova.', 'Ulamovi su sinovi bili hrabri junaci koji su zapinjali luk i imali mnogo sinova i unuka, sto pedeset. Svi su oni bili od Benjaminovih sinova.', '{"diff": [["replace", "luk", "l k"], ["replace", "si nova", "sinova"]]}', 0, 1, '2026-11-04T08:22:59+00:00') ON CONFLICT(id) DO UPDATE SET ref = excluded.ref, book_order = excluded.book_order, chapter = excluded.chapter, verse = excluded.verse, layer = excluded.layer, kind = excluded.kind, priority = excluded.priority, is_sample = excluded.is_sample, msg = excluded.msg, ks_text = excluded.ks_text, foi_text = excluded.foi_text, u68_text = excluded.u68_text, extra_json = excluded.extra_json, in_errata = excluded.in_errata, active = excluded.active, updated_at = excluded.updated_at;
INSERT INTO audit_findings (id, ref, book_order, chapter, verse, layer, kind, priority, is_sample, msg, ks_text, foi_text, u68_text, extra_json, in_errata, active, updated_at) VALUES ('0ef56efa91fa', 'Ezr 6,22', 15, 6, 22, 'tekst', 'ks_razlicit_od_foi', 2, 0, 'KS-online i FOI se razlikuju (U68 je treći, starije izdanje)', 'I svetkovahu radosno Blagdan beskvasnih kruhova sedam dana: jer ih je Jahve ispunio radošću i obratio prema njima srce asirskog kralja da ojača njihove ruke u radovima oko doma Boga, Boga Izraelova.', 'I svetkovahu radosno Blagdan beskvnih kruhova sedam dana: jer ih je Jahve ispunio radošću i obratio prema njima srce asirskog kralja da ojača njihove ruke u radovima oko doma Boga, Boga Izraelova.', 'I svetkovahu radosno Blagdan beskvasnih hljebova sedam dana: jer ih je Jahve ispunio radošću i obratio prema njima srce asirskog kralja da ojača njihove ruke u radovima oko Doma Boga, Boga Izraelova.', '{"diff": [["replace", "beskvasnih", "beskvnih"]]}', 0, 1, '2026-11-04T08:22:59+00:00') ON CONFLICT(id) DO UPDATE SET ref = excluded.ref, book_order = excluded.book_order, chapter = excluded.chapter, verse = excluded.verse, layer = excluded.layer, kind = excluded.kind, priority = excluded.priority, is_sample = excluded.is_sample, msg = excluded.msg, ks_text = excluded.ks_text, foi_text = excluded.foi_text, u68_text = excluded.u68_text, extra_json = excluded.extra_json, in_errata = excluded.in_errata, active = excluded.active, updated_at = excluded.updated_at;
INSERT INTO audit_findings (id, ref, book_order, chapter, verse, layer, kind, priority, is_sample, msg, ks_text, foi_text, u68_text, extra_json, in_errata, active, updated_at) VALUES ('0893ab70db83', 'Est 3,13', 19, 3, 13, 'tekst', 'ks_razlicit_od_foi', 2, 0, 'KS-online i FOI se razlikuju (U68 je treći, starije izdanje)', 'Po glasnicima razaslane su svim kraljevim pokrajinama poslanice da se svi Židovi, od dječaka do staraca, djeca i žene unište, pobiju, zatru, a njihova dobra da se zaplijene u jednom jedinom danu, i to trinaestog dana dvanaestog mjeseca, mjeseca adara. Ovo je prijepis poslanice: »Veliki kralj Ahasver upraviteljima sto dvadeset i sedam pokrajina od Indije do Etiopije i njima podložnim mjesnim glavarima ovako piše: Budući da imam vlast nad mnogim narodima i gospodstvo nad svim svijetom, odlučih, ne zanesen ohološću moći, nego u želji da uvijek blago i čovječno vladam, dati podanicima spokojan život i pružiti kraljevstvu blagostanje i slobodu kretanja po njemu te učvrstiti mir za kojim svi ljudi žude. Pošto sam zapitao savjetnike kako bi se moglo to ostvariti, Haman, koji se među nama izdvaja razboritošću i koji se ističe prokušanom odanošću i ustrajnom vjernošću i zauzima drugo mjesto u kraljevstvu, prokazao je da se među ostale narode svijeta zavukao jedan neprijateljski narod, svojim zakonima protivan svim pucima, narod koji vječno prezire kraljeve odluke tako te se ne može učvrstiti zajedničko carstvo kojim inače besprijekorno upravljamo. Ustanovili smo, dakle, da je samo taj narod neprekidno u sukobu sa svim ljudima, da se ističe načinom života što odstupa od zakona, da zbog neslaganja s našim naumima počinja najgora nedjela tako te se kraljevstvo ne može učvrstiti. Stoga naređujemo da se, zajedno sa ženama i djecom, neprijateljskim mačevima bez ikakva sažaljenja i milosrđa potpuno iskorijene oni koji vam budu naznačeni u pismima Hamana, upravitelja javnih poslova i našega drugog oca, i to četrnaestoga dana dvanaestoga mjeseca, adara, tekuće godine. Tako će se, pošto nekadašnji i današnji neprijatelji u jednom danu budu silovito strovaljeni u podzemlje, ubuduće za sva vremena naši poslovi moći odvijati postojano i nesmetano.«', 'Po glasnicima razaslane su svim kraljevim pokrajinama poslanice da se svi Židovi, od dječaka do staraca, djeca i žene unište, pobiju, zatru, a njihova dobra da se zaplijene u jednom jedinom danu, i to trinaestog dana dvanaestog mjeseca, mjeseca adara.', '', '{"diff": [["delete", "ovo je prijepis poslanice veliki kralj ahasver upraviteljima sto dvadeset i sedam pokrajina od indije do etiopije i njima podloznim mjesnim glavarima ovako pise buduci da imam vlast nad mnogim narodima i gospodstvo nad svim svijetom odlucih ne zanesen oholoscu moci nego u zelji da uvijek blago i covjecno vladam dati podanicima spokojan zivot i pruziti kraljevstvu blagostanje i slobodu kretanja po njemu te ucvrstiti mir za kojim svi ljudi zude posto sam zapitao savjetnike kako bi se moglo to ostvariti haman koji se među nama izdvaja razboritoscu i koji se istice prokusanom odanoscu i ustrajnom vjernoscu i zauzima drugo mjesto u kraljevstvu prokazao je da se među ostale narode svijeta zavukao jedan neprijateljski narod svojim zakonima protivan svim pucima narod koji vjecno prezire kraljeve odluke tako te se ne moze ucvrstiti zajednicko carstvo kojim inace besprijekorno upravljamo ustanovili smo dakle da je samo taj narod neprekidno u sukobu sa svim ljudima da se istice nacinom zivota sto odstupa od zakona da zbog neslaganja s nasim naumima pocinja najgora nedjela tako te se kraljevstvo ne moze ucvrstiti stoga naređujemo da se zajedno sa zenama i djecom neprijateljskim macevima bez ikakva sazaljenja i milosrđa potpuno iskorijene oni koji vam budu naznaceni u pismima hamana upravitelja javnih poslova i nasega drugog oca i to cetrnaestoga dana dvanaestoga mjeseca adara tekuce godine tako ce se posto nekadasnji i danasnji neprijatelji u jednom danu budu silovito strovaljeni u podzemlje ubuduce za sva vremena nasi poslovi moci odvijati postojano i nesmetano", ""]]}', 0, 1, '2026-11-04T08:22:59+00:00') ON CONFLICT(id) DO UPDATE SET ref = excluded.ref, book_order = excluded.book_order, chapter = excluded.chapter, verse = excluded.verse, layer = excluded.layer, kind = excluded.kind, priority = excluded.priority, is_sample = excluded.is_sample, msg = excluded.msg, ks_text = excluded.ks_text, foi_text = excluded.foi_text, u68_text = excluded.u68_text, extra_json = excluded.extra_json, in_errata = excluded.in_errata, active = excluded.active, updated_at = excluded.updated_at;
INSERT INTO audit_findings (id, ref, book_order, chapter, verse, layer, kind, priority, is_sample, msg, ks_text, foi_text, u68_text, extra_json, in_errata, active, updated_at) VALUES ('de85dd853b2d', 'Est 4,8', 19, 4, 8, 'tekst', 'ks_razlicit_od_foi', 2, 0, 'KS-online i FOI se razlikuju (U68 je treći, starije izdanje)', 'Dade mu i prijepis naredbe o njihovu zatoru, koja je objavljena u Suzi, da je pokaže Esteri te da joj javi i naloži neka ide kralju: neka ga moli za milost i posreduje kod njega za svoj narod. »Sjeti se dana siromaštva svoga kad sam te hranio rukom svojom, jer se Haman, drugi čovjek kraljevstva, dogovorio s kraljem da nas usmrti. Zazivaj Boga, govori kralju za nas i oslobodi nas od smrti.«', 'Dade mu i prijepis naredbe o njihovu zatoru, koja je objavljena u Suzi, da je pokaže Esteri te da joj javi i naloži neka ide kralju: neka ga moli za milost i posreduje kod njega za svoj narod.', '', '{"diff": [["delete", "sjeti se dana siromastva svoga kad sam te hranio rukom svojom jer se haman drugi covjek kraljevstva dogovorio s kraljem da nas usmrti zazivaj boga govori kralju za nas i oslobodi nas od smrti", ""]]}', 0, 1, '2026-11-04T08:22:59+00:00') ON CONFLICT(id) DO UPDATE SET ref = excluded.ref, book_order = excluded.book_order, chapter = excluded.chapter, verse = excluded.verse, layer = excluded.layer, kind = excluded.kind, priority = excluded.priority, is_sample = excluded.is_sample, msg = excluded.msg, ks_text = excluded.ks_text, foi_text = excluded.foi_text, u68_text = excluded.u68_text, extra_json = excluded.extra_json, in_errata = excluded.in_errata, active = excluded.active, updated_at = excluded.updated_at;
INSERT INTO audit_findings (id, ref, book_order, chapter, verse, layer, kind, priority, is_sample, msg, ks_text, foi_text, u68_text, extra_json, in_errata, active, updated_at) VALUES ('0f673e239398', 'Est 4,17', 19, 4, 17, 'tekst', 'ks_razlicit_od_foi', 2, 0, 'KS-online i FOI se razlikuju (U68 je treći, starije izdanje)', 'Mordokaj se onda povuče i učini što mu je naredila Estera. I sjetivši se svih djela koje je Gospod izveo, pomoli se Gospodu i kaza: »Gospode, Gospode, kralju koji vladaš nad svime, sve je u tvojoj vlasti i nema toga koji bi se mogao suprotstaviti tvojoj volji da spasiš Izraela! Ti si stvorio nebo i zemlju i sve što je divljenja vrijedno pod nebom. Gospodar si svega i nema toga koji se može tebi oprijeti, Gospodine! Tebi je sve poznato; ti znaš, Gospodine: nisam pao ničice pred bahatog Hamana, ali ne iz drskosti, ni iz oholosti, ni iz častoljublja. Ti znaš da bih za spas Izraela bio voljan i tabane njegove cjelivati. To sam učinio zato da ne metnem čast koja se iskazuje čovjeku iznad one koja se iskazuje Bogu. Neću pasti ničice ni pred kim, nego samo pred tobom, moj Gospodine, i to ne činim iz oholosti. Sada, Gospodine, Bože, kralju, Bože Abrahamov, poštedi narod svoj, jer gledaju samo kako bi nas istrijebili: žele uništiti ono što je od početka bila tvoja baština. Nemoj zanemariti posjed svoj koji si oslobodio iz egipatske zemlje! Poslušaj molitvu moju, budi milostiv nasljedstvu svome i u veselje prometni plač naš, da bismo, ostavši živi, mogli hvalospjevima slaviti ime tvoje i nemoj dopustiti da iščeznu usta onih koji te hvale, o Gospode!« I sav je Izrael vapio svom snagom svojom, jer je smrt bila pred očima njihovim. I kraljica se Estera, obuzeta smrtnom tjeskobom, uteče Gospodinu. Pošto svuče sa sebe sjajne haljine, navuče odjeću tjeskobe i žalosti, te umjesto skupocjenim mirisima posu glavu pepelom i prahom. I ponizi veoma tijelo svoje postom, a svako mjesto na kojem se u znak veselja znala ukrašavati posu uvojcima svoje kose, pomoli se Bogu Izraelovu i kaza: »Gospodine moj, kralju naš, ti si jedini! Dođi u pomoć meni koja sam sama, kojoj nema druge pomoći do tebe, jer opasnost je moja u ruci mojoj. Ja sam od svoga djetinjstva slušala u obiteljskom rodu da si ti, Gospode, izabrao Izraela među svim drugim narodima: naše očeve među svim njihovim precima u svoju trajnu baštinu i da si za njih učinio sve što si im obećao. Ali smo sad sagriješili pred tobom i ti si nas predao u ruke neprijatelja naših jer smo iskazivali počast bogovima njihovim. Pravedan si, Gospodine! I sad oni, nezadovoljni već gorčinom sužanjstva našega, staviše ruke svoje u ruke kumira svojih da će poništiti odredbu usta tvojih, uništiti baštinu tvoju, začepiti usta onima koji te hvale i utrnuti slavu doma tvoga i žrtvenika tvoga, a otvoriti usta narodâ da hvale njihove isprazne kumire i dive se jednom kralju od mesa. Nemoj predati, Gospode, žezlo svoje onima koji ne postoje. Neka se ne smiju propasti našoj, nego okreni naum njihov na njihove glave i primjerno kazni onoga koji je počeo bjesniti protiv nas. Sjeti se, Gospode! Objavi se u vrijeme naših jadâ i ohrabri me, o kralju bogova i vladaru svakoga gospodstva! Metni u moja usta primjerenu riječ pred lavom, a njegovo srce zadahni mržnjom na neprijatelja našega; da zatre njega i njegove sumišljenike. A nas oslobodi rukom svojom i dođi u pomoć meni koja sam sama i nemam nego tebe, o Gospode! Sve ti je poznato pa znaš da mrzim slavu opakih i da mi je odvratna postelja neobrezanih i svakoga tuđinca. Znaš tjeskobu moju, jer ja se gnušam nad znamenjem moga visočanstva koje se nalazi na glavi mojoj. U dane kad se s njime pojavim, grstim se nad njim kao nad dronjkom mjesečnog pranja i ne nosim ga onih dana koji pripadaju samo meni. Sluškinja tvoja nije nikada jela sa stola Hamanova, nisam nikada počastila kraljevsku gozbu, niti sam pila vino ljevanica. I od dana uzdignuća svoga do danas sluškinja tvoja nije se poveselila osim u tebi, Gospode, Bože Abrahamov. Bože, nadasve moćni, uslišaj glas beznadnih i izbavi nas iz ruku opakih, a oslobodi i mene od moga straha!«', 'Mordokaj se onda povuče i učini što mu je naredila Estera.', '', '{"diff": [["delete", "i sjetivsi se svih djela koje je gospod izveo pomoli se gospodu i kaza gospode gospode kralju koji vladas nad svime sve je u tvojoj vlasti i nema toga koji bi se mogao suprotstaviti tvojoj volji da spasis izraela ti si stvorio nebo i zemlju i sve sto je divljenja vrijedno pod nebom gospodar si svega i nema toga koji se moze tebi oprijeti gospodine tebi je sve poznato ti znas gospodine nisam pao nicice pred bahatog hamana ali ne iz drskosti ni iz oholosti ni iz castoljublja ti znas da bih za spas izraela bio voljan i tabane njegove cjelivati to sam ucinio zato da ne metnem cast koja se iskazuje covjeku iznad one koja se iskazuje bogu necu pasti nicice ni pred kim nego samo pred tobom moj gospodine i to ne cinim iz oholosti sada gospodine boze kralju boze abrahamov postedi narod svoj jer gledaju samo kako bi nas istrijebili zele unistiti ono sto je od pocetka bila tvoja bastina nemoj zanemariti posjed svoj koji si oslobodio iz egipatske zemlje poslusaj molitvu moju budi milostiv nasljedstvu svome i u veselje prometni plac nas da bismo ostavsi zivi mogli hvalospjevima slaviti ime tvoje i nemoj dopustiti da isceznu usta onih koji te hvale o gospode i sav je izrael vapio svom snagom svojom jer je smrt bila pred ocima njihovim i kraljica se estera obuzeta smrtnom tjeskobom utece gospodinu posto svuce sa sebe sjajne haljine navuce odjecu tjeskobe i zalosti te umjesto skupocjenim mirisima posu glavu pepelom i prahom i ponizi veoma tijelo svoje postom a svako mjesto na kojem se u znak veselja znala ukrasavati posu uvojcima svoje kose pomoli se bogu izraelovu i kaza gospodine moj kralju nas ti si jedini dođi u pomoc meni koja sam sama kojoj nema druge pomoci do tebe jer opasnost je moja u ruci mojoj ja sam od svoga djetinjstva slusala u obiteljskom rodu da si ti gospode izabrao izraela među svim drugim narodima nase oceve među svim njihovim precima u svoju trajnu bastinu i da si za njih ucinio sve sto si im obecao ali smo sad sagrijesili pred tobom i ti si nas predao u ruke neprijatelja nasih jer smo iskazivali pocast bogovima njihovim pravedan si gospodine i sad oni nezadovoljni vec gorcinom suzanjstva nasega stavise ruke svoje u ruke kumira svojih da ce ponistiti odredbu usta tvojih unistiti bastinu tvoju zacepiti usta onima koji te hvale i utrnuti slavu doma tvoga i zrtvenika tvoga a otvoriti usta naroda da hvale njihove isprazne kumire i dive se jednom kralju od mesa nemoj predati gospode zezlo svoje onima koji ne postoje neka se ne smiju propasti nasoj nego okreni naum njihov na njihove glave i primjerno kazni onoga koji je poceo bjesniti protiv nas sjeti se gospode objavi se u vrijeme nasih jada i ohrabri me o kralju bogova i vladaru svakoga gospodstva metni u moja usta primjerenu rijec pred lavom a njegovo srce zadahni mrznjom na neprijatelja nasega da zatre njega i njegove sumisljenike a nas oslobodi rukom svojom i dođi u pomoc meni koja sam sama i nemam nego tebe o gospode sve ti je poznato pa znas da mrzim slavu opakih i da mi je odvratna postelja neobrezanih i svakoga tuđinca znas tjeskobu moju jer ja se gnusam nad znamenjem moga visocanstva koje se nalazi na glavi mojoj u dane kad se s njime pojavim grstim se nad njim kao nad dronjkom mjesecnog pranja i ne nosim ga onih dana koji pripadaju samo meni sluskinja tvoja nije nikada jela sa stola hamanova nisam nikada pocastila kraljevsku gozbu niti sam pila vino ljevanica i od dana uzdignuca svoga do danas sluskinja tvoja nije se poveselila osim u tebi gospode boze abrahamov boze nadasve mocni uslisaj glas beznadnih i izbavi nas iz ruku opakih a oslobodi i mene od moga straha", ""]]}', 0, 1, '2026-11-04T08:22:59+00:00') ON CONFLICT(id) DO UPDATE SET ref = excluded.ref, book_order = excluded.book_order, chapter = excluded.chapter, verse = excluded.verse, layer = excluded.layer, kind = excluded.kind, priority = excluded.priority, is_sample = excluded.is_sample, msg = excluded.msg, ks_text = excluded.ks_text, foi_text = excluded.foi_text, u68_text = excluded.u68_text, extra_json = excluded.extra_json, in_errata = excluded.in_errata, active = excluded.active, updated_at = excluded.updated_at;
INSERT INTO audit_findings (id, ref, book_order, chapter, verse, layer, kind, priority, is_sample, msg, ks_text, foi_text, u68_text, extra_json, in_errata, active, updated_at) VALUES ('65ac29d41fb9', 'Est 5,1', 19, 5, 1, 'tekst', 'ks_razlicit_od_foi', 2, 0, 'KS-online i FOI se razlikuju (U68 je treći, starije izdanje)', 'Trećega dana, pošto presta moliti, svuče molitvene haljine i zaodjenu se slavom svojom. Tako čarobna zazva Boga svevida i spasitelja. Onda uze dvije sluškinje. Na jednu se gotovo nježno naslanjala, a druga ju je slijedila i pridržavala njezinu odjeću. Blistala je od vrhunske ljepote, lice joj bijaše veselo, kao rastvoreno ljubavi, a srce sapeto od straha. Kroza sva je vrata ušla pred kralja. On je sjedio na svom kraljevskom prijestolju, zaogrnut svim ukrasom veličanstva svoga, sav u zlatu i dragom kamenju, ulijevao je veliko strahopoštovanje. Podigavši svoje lice, sjajem ozaren, pogleda krajnje ljutit. Kraljici pozli. Od slabosti problijedje i klonu na glavu sluškinje što je pred njom išla. Tada Bog sklonu kraljevu dušu na blagost. Zabrinut, kralj skoči sa svoga prijestolja i uze je u naručje dok ne dođe k sebi. Hrabrio ju je utješnim riječima i upitao: »Što je, Estero? Ja sam tvoj brat! Ne boj se, nećeš umrijeti – naša je uredba za obične ljude. Priđi!«', 'Trećega dana, pošto presta moliti, svuče molitvene haljine i zaodjenu se slavom svojom.', '', '{"diff": [["delete", "tako carobna zazva boga svevida i spasitelja onda uze dvije sluskinje na jednu se gotovo njezno naslanjala a druga ju je slijedila i pridrzavala njezinu odjecu blistala je od vrhunske ljepote lice joj bijase veselo kao rastvoreno ljubavi a srce sapeto od straha kroza sva je vrata usla pred kralja on je sjedio na svom kraljevskom prijestolju zaogrnut svim ukrasom velicanstva svoga sav u zlatu i dragom kamenju ulijevao je veliko strahopostovanje podigavsi svoje lice sjajem ozaren pogleda krajnje ljutit kraljici pozli od slabosti problijedje i klonu na glavu sluskinje sto je pred njom isla tada bog sklonu kraljevu dusu na blagost zabrinut kralj skoci sa svoga prijestolja i uze je u narucje dok ne dođe k sebi hrabrio ju je utjesnim rijecima i upitao sto je estero ja sam tvoj brat ne boj se neces umrijeti nasa je uredba za obicne ljude priđi", ""]]}', 0, 1, '2026-11-04T08:22:59+00:00') ON CONFLICT(id) DO UPDATE SET ref = excluded.ref, book_order = excluded.book_order, chapter = excluded.chapter, verse = excluded.verse, layer = excluded.layer, kind = excluded.kind, priority = excluded.priority, is_sample = excluded.is_sample, msg = excluded.msg, ks_text = excluded.ks_text, foi_text = excluded.foi_text, u68_text = excluded.u68_text, extra_json = excluded.extra_json, in_errata = excluded.in_errata, active = excluded.active, updated_at = excluded.updated_at;
INSERT INTO audit_findings (id, ref, book_order, chapter, verse, layer, kind, priority, is_sample, msg, ks_text, foi_text, u68_text, extra_json, in_errata, active, updated_at) VALUES ('9258c626d0aa', 'Est 5,2', 19, 5, 2, 'tekst', 'ks_razlicit_od_foi', 2, 0, 'KS-online i FOI se razlikuju (U68 je treći, starije izdanje)', 'I podigavši zlatno žezlo, postavi ga na vrat Esteri, zagrli je i reče: »Govori mi!« Ona mu reče: »Spazih te, gospodaru, kao anđela Božjega, pa mi se uznemiri srce od straha pred sjajem tvojim. Jer si, gospodaru, divan i lice ti je puno dražesti.« Dok je još govorila, klonu od iznemoglosti. Kralj se uznemiri, a sva ju je posluga njegova hrabrila.', 'I podigavši zlatno žezlo, postavi ga na vrat Esteri, zagrli je i reče: »Govori mi!«', '', '{"diff": [["delete", "ona mu rece spazih te gospodaru kao anđela bozjega pa mi se uznemiri srce od straha pred sjajem tvojim jer si gospodaru divan i lice ti je puno drazesti dok je jos govorila klonu od iznemoglosti kralj se uznemiri a sva ju je posluga njegova hrabrila", ""]]}', 0, 1, '2026-11-04T08:22:59+00:00') ON CONFLICT(id) DO UPDATE SET ref = excluded.ref, book_order = excluded.book_order, chapter = excluded.chapter, verse = excluded.verse, layer = excluded.layer, kind = excluded.kind, priority = excluded.priority, is_sample = excluded.is_sample, msg = excluded.msg, ks_text = excluded.ks_text, foi_text = excluded.foi_text, u68_text = excluded.u68_text, extra_json = excluded.extra_json, in_errata = excluded.in_errata, active = excluded.active, updated_at = excluded.updated_at;
INSERT INTO audit_findings (id, ref, book_order, chapter, verse, layer, kind, priority, is_sample, msg, ks_text, foi_text, u68_text, extra_json, in_errata, active, updated_at) VALUES ('e7ae2fd7963f', 'Est 8,12', 19, 8, 12, 'tekst', 'ks_razlicit_od_foi', 2, 0, 'KS-online i FOI se razlikuju (U68 je treći, starije izdanje)', 'sve istoga dana u svim pokrajinama kraljevstva Ahasverova: trinaestog dana dvanaestoga mjeseca, to jest mjeseca adara. Prijepis toga pisma glasi: »Veliki kralj Ahasver namjesnicima u sto dvadeset i sedam pokrajina od Indije do Etiopije, upraviteljima pokrajina i svima svojim vjernim podanicima, pozdrav! Mnogi, koliko su više obasuti častima, poradi velike dobrodušnosti svojih dobročinitelja, toliko se više znaju uzobijestiti zbog toga. Pa ne samo da nastoje nanijeti zlo našim podanicima nego, nesposobni da obuzdaju bahatost, namještaju zamku i samim svojim dobročiniteljima. Oni ne samo da iskorjenjuju osjećaj harnosti nego, zaneseni nadutošću onih koji ne znaju za dobro, umišljaju da će umaknuti Bogu koji sve vidi i pravdi koja mrzi zlo. Često i mnogi od onih koji su na vlasti, kad upravu državnih poslova povjere prijateljima, pod njihovim utjecajem postanu sukrivci nevine krvi i zapletu se u nepopravljive nevolje: smicalice, licemjerje i pokvarenosti izigraju čestitu dobronamjernost upravitelja. To se može vidjeti ne toliko iz starijih povijesti koje su do nas doprle: istražite samo kolike je zločine pred našim očima počinila opakost nedostojnih vladara. Zato ćemo se ubuduće truditi da svim ljudima damo mirno i spokojno kraljevstvo. Uvest ćemo promjene, a što nam se na uvid podastre prosuđivat ćemo s najdobrohotnijom susretljivošću. Tako smo Hamana, sina Hamdatina, Makedonca, koji je doista stran krvi Perzijanaca i jako daleko od naše naklonosti, primili kao gosta, a on se toliko okoristio dobrohotnošću koju gajimo prema svakom narodu da je bio nazvan našim ocem i bio poštovan od svih jer je zauzimao drugo mjesto, najbliže kraljevskom prijestolju. Ali ne znajući obuzdati svoju oholost, smisli kako bi nas lišio kraljevstva i života, tražeći da mnogovrsnim spletkama uništi Mordokaja, našeg spasitelja i trajnog dobročinitelja, i našu neporočnu družicu kraljevstva, Esteru, sa svim njihovim narodom. Mislio je da će nas tako osamljene zaskočiti i prenijeti vlast Perzijanaca u ruke Makedonaca. Ali smo mi utvrdili da Židovi koje je taj zlikovac naumio zatrti ne samo da nisu zlotvori nego su, upravljani najpravednijim zakonima, sinovi Najvišega, Najvećega, živoga Boga koji čuva nama, kao i našim djedovima, carstvo u najboljem redu. Učinit ćete, dakle, dobro ne budete li se poslužili pismima koja je uputio Haman, Hamdatov sin, jer je on, tvorac toga zločina, već obješen sa svom obitelji pred vratima Suze: Bog, koji vlada nad svime, smjesta mu je dosudio zasluženu kaznu. Izloživši na svakom mjestu prijepis ove naredbe, pustite da se Židovi služe slobodno svojim zakonima. Pomognite im da uzmognu s uspjehom odbitiod sebe one koji bi ih napali u času nevolje trinaestoga dana dvanaestoga mjeseca, mjeseca adara, jer je baš to dan u koji je Bog, gospodar svega, izabranom narodu donio radost mjesto uništenja. Zato i vi među svojim spomen-blagdanima svetkujte u svoj svečanosti ovaj osobiti dan da bi sada i ubuduće bio vama i Perzijancima dobre volje na spas, a našim neprijateljima spomen na propast. Svaki grad ili uopće pokrajina koja se ovoga ne bude pridržavala bit će nesmiljeno kopljem i ognjem uništena: postat će ne samo ljudima nepristupačna nego i zvijerima i pticama zauvijek mrska.«', 'sve istoga dana u svim pokrajinama kraljevstva Ahasverova: trinaestog dana dvanaestoga mjeseca, to jest mjeseca adara.', '', '{"diff": [["delete", "prijepis toga pisma glasi veliki kralj ahasver namjesnicima u sto dvadeset i sedam pokrajina od indije do etiopije upraviteljima pokrajina i svima svojim vjernim podanicima pozdrav mnogi koliko su vise obasuti castima poradi velike dobrodusnosti svojih dobrocinitelja toliko se vise znaju uzobijestiti zbog toga pa ne samo da nastoje nanijeti zlo nasim podanicima nego nesposobni da obuzdaju bahatost namjestaju zamku i samim svojim dobrociniteljima oni ne samo da iskorjenjuju osjecaj harnosti nego zaneseni nadutoscu onih koji ne znaju za dobro umisljaju da ce umaknuti bogu koji sve vidi i pravdi koja mrzi zlo cesto i mnogi od onih koji su na vlasti kad upravu drzavnih poslova povjere prijateljima pod njihovim utjecajem postanu sukrivci nevine krvi i zapletu se u nepopravljive nevolje smicalice licemjerje i pokvarenosti izigraju cestitu dobronamjernost upravitelja to se moze vidjeti ne toliko iz starijih povijesti koje su do nas doprle istrazite samo kolike je zlocine pred nasim ocima pocinila opakost nedostojnih vladara zato cemo se ubuduce truditi da svim ljudima damo mirno i spokojno kraljevstvo uvest cemo promjene a sto nam se na uvid podastre prosuđivat cemo s najdobrohotnijom susretljivoscu tako smo hamana sina hamdatina makedonca koji je doista stran krvi perzijanaca i jako daleko od nase naklonosti primili kao gosta a on se toliko okoristio dobrohotnoscu koju gajimo prema svakom narodu da je bio nazvan nasim ocem i bio postovan od svih jer je zauzimao drugo mjesto najblize kraljevskom prijestolju ali ne znajuci obuzdati svoju oholost smisli kako bi nas lisio kraljevstva i zivota trazeci da mnogovrsnim spletkama unisti mordokaja naseg spasitelja i trajnog dobrocinitelja i nasu neporocnu druzicu kraljevstva esteru sa svim njihovim narodom mislio je da ce nas tako osamljene zaskociti i prenijeti vlast perzijanaca u ruke makedonaca ali smo mi utvrdili da zidovi koje je taj zlikovac naumio zatrti ne samo da nisu zlotvori nego su upravljani najpravednijim zakonima sinovi najvisega najvecega zivoga boga koji cuva nama kao i nasim djedovima carstvo u najboljem redu ucinit cete dakle dobro ne budete li se posluzili pismima koja je uputio haman hamdatov sin jer je on tvorac toga zlocina vec objesen sa svom obitelji pred vratima suze bog koji vlada nad svime smjesta mu je dosudio zasluzenu kaznu izlozivsi na svakom mjestu prijepis ove naredbe pustite da se zidovi sluze slobodno svojim zakonima pomognite im da uzmognu s uspjehom odbitiod sebe one koji bi ih napali u casu nevolje trinaestoga dana dvanaestoga mjeseca mjeseca adara jer je bas to dan u koji je bog gospodar svega izabranom narodu donio radost mjesto unistenja zato i vi među svojim spomen blagdanima svetkujte u svoj svecanosti ovaj osobiti dan da bi sada i ubuduce bio vama i perzijancima dobre volje na spas a nasim neprijateljima spomen na propast svaki grad ili uopce pokrajina koja se ovoga ne bude pridrzavala bit ce nesmiljeno kopljem i ognjem unistena postat ce ne samo ljudima nepristupacna nego i zvijerima i pticama zauvijek mrska", ""]]}', 0, 1, '2026-11-04T08:22:59+00:00') ON CONFLICT(id) DO UPDATE SET ref = excluded.ref, book_order = excluded.book_order, chapter = excluded.chapter, verse = excluded.verse, layer = excluded.layer, kind = excluded.kind, priority = excluded.priority, is_sample = excluded.is_sample, msg = excluded.msg, ks_text = excluded.ks_text, foi_text = excluded.foi_text, u68_text = excluded.u68_text, extra_json = excluded.extra_json, in_errata = excluded.in_errata, active = excluded.active, updated_at = excluded.updated_at;
INSERT INTO audit_findings (id, ref, book_order, chapter, verse, layer, kind, priority, is_sample, msg, ks_text, foi_text, u68_text, extra_json, in_errata, active, updated_at) VALUES ('dab3a5d1f78f', 'Est 9,19', 19, 9, 19, 'tekst', 'ks_razlicit_od_foi', 2, 0, 'KS-online i FOI se razlikuju (U68 je treći, starije izdanje)', 'Zbog toga Židovi pripoljci, oni koji žive po neutvrđenim selima, blagdanski svetkuju četrnaesti dan mjeseca adara veseleći se i gozbujući i među sobom izmjenjujući darove. A koji žive u gradovima slave i petnaesti dan adara u razdraganosti i u veselju, izmjenjujući među sobom darove.', 'Zbog toga Židovi pripoljci, oni koji žive po neutvrđenim selima, blagdanski svetkuju četrnaesti dan mjeseca adara veseleći se i gozbujući i među sobom izmjenjujući darove.', '', '{"diff": [["delete", "a koji zive u gradovima slave i petnaesti dan adara u razdraganosti i u veselju izmjenjujuci među sobom darove", ""]]}', 0, 1, '2026-11-04T08:22:59+00:00') ON CONFLICT(id) DO UPDATE SET ref = excluded.ref, book_order = excluded.book_order, chapter = excluded.chapter, verse = excluded.verse, layer = excluded.layer, kind = excluded.kind, priority = excluded.priority, is_sample = excluded.is_sample, msg = excluded.msg, ks_text = excluded.ks_text, foi_text = excluded.foi_text, u68_text = excluded.u68_text, extra_json = excluded.extra_json, in_errata = excluded.in_errata, active = excluded.active, updated_at = excluded.updated_at;
INSERT INTO audit_findings (id, ref, book_order, chapter, verse, layer, kind, priority, is_sample, msg, ks_text, foi_text, u68_text, extra_json, in_errata, active, updated_at) VALUES ('04f00ee1013b', 'Est 10,3', 19, 10, 3, 'tekst', 'ks_razlicit_od_foi', 2, 0, 'KS-online i FOI se razlikuju (U68 je treći, starije izdanje)', 'kako je Židov Mordokaj bio prvi iza kralja Ahasvera, velik u očima Židova, voljen od mnoštva svoje subraće kao pobornik blagostanja svoga naroda i glasnik mira za svoj rod. Mordokaj uskliknu: »Božje je to djelo! Sjećam se, evo, sna koji sam o tom usnio – ništa nije ostalo neispunjeno: malen izvor koji posta rijeka, svjetlo, sunce i voda u izobilju. Rijeka je Estera kojom se kralj oženio i učinio je kraljicom. Dva zmaja, to smo ja i Haman. Narodi, to su svi oni koji su se udružili da bi zatrli ime židovsko. Moj narod, to je Izrael – oni koji podigoše svoj glas k Bogu i biše spašeni. D a , Gospod spasi svoj narod! Gospod nas oslobodi svih onih zala! Bog izvede znakove i čudesa kakvih nema među poganima! Zato on baca dva ždrijeba: jedan za Božji puk, drugi za sve ostale narode. I oba ova ždrijeba izađoše u čas, vrijeme i dan koji je dosudio Bog za sve narode. Sjetio se Bog naroda svoga i dosudio pravdu baštini svojoj. I bit će im – narodu njegovu Izraelu – ovi dani mjeseca adara, to jest četrnaesti i petnaesti, dani okupljanja, radosti i veselja pred Bogom za pokoljenja dovijeka.« Četvrte godine kraljevanja Ptolemejeva i Kleopatrina, Dositej, koji se kazao kao svećenik i levit, i njegov sin Ptolemej doniješe ovo pismo o Purimu, tvrdeći da je vjerodostojno i da ga je preveo Lizimah, sin Ptolemejev, iz Jeruzalema.', 'kako je Židov Mordokaj bio prvi iza kralja Ahasvera, velik u očima Židova, voljen od mnoštva svoje subraće kao pobornik blagostanja svoga naroda i glasnik mira za svoj rod.', '', '{"diff": [["delete", "mordokaj uskliknu bozje je to djelo sjecam se evo sna koji sam o tom usnio nista nije ostalo neispunjeno malen izvor koji posta rijeka svjetlo sunce i voda u izobilju rijeka je estera kojom se kralj ozenio i ucinio je kraljicom dva zmaja to smo ja i haman narodi to su svi oni koji su se udruzili da bi zatrli ime zidovsko moj narod to je izrael oni koji podigose svoj glas k bogu i bise spaseni d a gospod spasi svoj narod gospod nas oslobodi svih onih zala bog izvede znakove i cudesa kakvih nema među poganima zato on baca dva zdrijeba jedan za bozji puk drugi za sve ostale narode i oba ova zdrijeba izađose u cas vrijeme i dan koji je dosudio bog za sve narode sjetio se bog naroda svoga i dosudio pravdu bastini svojoj i bit ce im narodu njegovu izraelu ovi dani mjeseca adara to jest cetrnaesti i petnaesti dani okupljanja radosti i veselja pred bogom za pokoljenja dovijeka cetvrte godine kraljevanja ptolemejeva i kleopatrina dositej koji se kazao kao svecenik i levit i njegov sin ptolemej donijese ovo pismo o purimu tvrdeci da je vjerodostojno i da ga je preveo lizimah sin ptolemejev iz jeruzalema", ""]]}', 0, 1, '2026-11-04T08:22:59+00:00') ON CONFLICT(id) DO UPDATE SET ref = excluded.ref, book_order = excluded.book_order, chapter = excluded.chapter, verse = excluded.verse, layer = excluded.layer, kind = excluded.kind, priority = excluded.priority, is_sample = excluded.is_sample, msg = excluded.msg, ks_text = excluded.ks_text, foi_text = excluded.foi_text, u68_text = excluded.u68_text, extra_json = excluded.extra_json, in_errata = excluded.in_errata, active = excluded.active, updated_at = excluded.updated_at;
INSERT INTO audit_findings (id, ref, book_order, chapter, verse, layer, kind, priority, is_sample, msg, ks_text, foi_text, u68_text, extra_json, in_errata, active, updated_at) VALUES ('c647bb866e6d', '1 Mak 6,47', 20, 6, 47, 'tekst', 'ks_razlicit_od_foi', 2, 0, 'KS-online i FOI se razlikuju (U68 je treći, starije izdanje)', 'Židovi su, videći silnu kraljevsku snagu i žestoku vojsku, pred njom uzmaknuli.', 'Židovi su, videći silnu kraljevsku snagu i žestoku vojsku, pred njom uzmaknuli. Zauzeće Betsura i sirijska opsada gore Siona', 'Židovi su, videći silnu kraljevsku snagu i žestoku vojsku, pred njom uzmakli.', '{"diff": [["insert", "", "zauzece betsura i sirijska opsada gore siona"]]}', 0, 1, '2026-11-04T08:22:59+00:00') ON CONFLICT(id) DO UPDATE SET ref = excluded.ref, book_order = excluded.book_order, chapter = excluded.chapter, verse = excluded.verse, layer = excluded.layer, kind = excluded.kind, priority = excluded.priority, is_sample = excluded.is_sample, msg = excluded.msg, ks_text = excluded.ks_text, foi_text = excluded.foi_text, u68_text = excluded.u68_text, extra_json = excluded.extra_json, in_errata = excluded.in_errata, active = excluded.active, updated_at = excluded.updated_at;
INSERT INTO audit_findings (id, ref, book_order, chapter, verse, layer, kind, priority, is_sample, msg, ks_text, foi_text, u68_text, extra_json, in_errata, active, updated_at) VALUES ('30a943e76de5', '1 Mak 11,53', 20, 11, 53, 'tekst', 'ks_razlicit_od_foi', 2, 0, 'KS-online i FOI se razlikuju (U68 je treći, starije izdanje)', 'Ali je prekršio sva svoja obećanja, zavadio se s Jonatanom, nije više priznavao njegovih usluga, nego ga silno žalostio.', 'Ali je prekršio sva svoja obećanja, zavadio se s Jonatanom, nije više priznavao njegovih usluga, nego ga silno žalostio. Jonatan protiv Demetrija II. – Šimun ponovno osvaja Betsur – Okršaj kod Hasora', 'Ali je prekršio sva svoja obećanja, zavadio se s Jonatanom, nije više priznavao njegovih usluga nego ga silno žalostio. Okršaj kod Hasora', '{"diff": [["insert", "", "jonatan protiv demetrija ii simun ponovno osvaja betsur okrsaj kod hasora"]]}', 0, 1, '2026-11-04T08:22:59+00:00') ON CONFLICT(id) DO UPDATE SET ref = excluded.ref, book_order = excluded.book_order, chapter = excluded.chapter, verse = excluded.verse, layer = excluded.layer, kind = excluded.kind, priority = excluded.priority, is_sample = excluded.is_sample, msg = excluded.msg, ks_text = excluded.ks_text, foi_text = excluded.foi_text, u68_text = excluded.u68_text, extra_json = excluded.extra_json, in_errata = excluded.in_errata, active = excluded.active, updated_at = excluded.updated_at;
