INSERT INTO audit_findings (id, ref, book_order, chapter, verse, layer, kind, priority, is_sample, msg, ks_text, foi_text, u68_text, extra_json, in_errata, active, updated_at) VALUES ('dbb2fa4c80bf', 'Jdt 14,13', 18, 14, 13, 'tekst', 'naglasak', 3, 0, 'FOI ovdje ima naglašeno slovo (pokvareno u ''?''); provjeriti ima li tisak naglasak koji KS-online nema', 'Dođoše do Holofernova šatora pa kazaše upravitelju njegovih dobara: »De probudi našega gospodara. Oni su se robovi usudili sići i napasti nas da zauvijek budu uništeni.«', 'Dođoše do Holofernova šatora pa kazaše upravitelju njegovih dobara: »D? probudi našega gospodara. Oni su se robovi usudili sići i napasti nas da zauvijek budu uništeni.«', '', '{}', 0, 1, '2026-11-04T08:22:59+00:00') ON CONFLICT(id) DO UPDATE SET ref = excluded.ref, book_order = excluded.book_order, chapter = excluded.chapter, verse = excluded.verse, layer = excluded.layer, kind = excluded.kind, priority = excluded.priority, is_sample = excluded.is_sample, msg = excluded.msg, ks_text = excluded.ks_text, foi_text = excluded.foi_text, u68_text = excluded.u68_text, extra_json = excluded.extra_json, in_errata = excluded.in_errata, active = excluded.active, updated_at = excluded.updated_at;
INSERT INTO audit_findings (id, ref, book_order, chapter, verse, layer, kind, priority, is_sample, msg, ks_text, foi_text, u68_text, extra_json, in_errata, active, updated_at) VALUES ('a5d79fa0ccd0', 'Est 8,6', 19, 8, 6, 'tekst', 'naglasak', 3, 0, 'FOI ovdje ima naglašeno slovo (pokvareno u ''?''); provjeriti ima li tisak naglasak koji KS-online nema', 'Ta kako bih ja mogla gledati nesreću koja bi pogodila moj narod? Kako bih mogla gledati zator roda svoga?«', 'T? kako bih ja mogla gledati nesreću koja bi pogodila moj narod? Kako bih mogla gledati zator roda svoga?«', '', '{}', 0, 1, '2026-11-04T08:22:59+00:00') ON CONFLICT(id) DO UPDATE SET ref = excluded.ref, book_order = excluded.book_order, chapter = excluded.chapter, verse = excluded.verse, layer = excluded.layer, kind = excluded.kind, priority = excluded.priority, is_sample = excluded.is_sample, msg = excluded.msg, ks_text = excluded.ks_text, foi_text = excluded.foi_text, u68_text = excluded.u68_text, extra_json = excluded.extra_json, in_errata = excluded.in_errata, active = excluded.active, updated_at = excluded.updated_at;
INSERT INTO audit_findings (id, ref, book_order, chapter, verse, layer, kind, priority, is_sample, msg, ks_text, foi_text, u68_text, extra_json, in_errata, active, updated_at) VALUES ('cdea81f5717f', 'Est 10,3', 19, 10, 3, 'tipografija', 'razmak_prije_interpunkcije', 3, 0, '„…u i biše spašeni. D a , Gospod spasi svoj n…”', 'kako je Židov Mordokaj bio prvi iza kralja Ahasvera, velik u očima Židova, voljen od mnoštva svoje subraće kao pobornik blagostanja svoga naroda i glasnik mira za svoj rod. Mordokaj uskliknu: »Božje je to djelo! Sjećam se, evo, sna koji sam o tom usnio – ništa nije ostalo neispunjeno: malen izvor koji posta rijeka, svjetlo, sunce i voda u izobilju. Rijeka je Estera kojom se kralj oženio i učinio je kraljicom. Dva zmaja, to smo ja i Haman. Narodi, to su svi oni koji su se udružili da bi zatrli ime židovsko. Moj narod, to je Izrael – oni koji podigoše svoj glas k Bogu i biše spašeni. D a , Gospod spasi svoj narod! Gospod nas oslobodi svih onih zala! Bog izvede znakove i čudesa kakvih nema među poganima! Zato on baca dva ždrijeba: jedan za Božji puk, drugi za sve ostale narode. I oba ova ždrijeba izađoše u čas, vrijeme i dan koji je dosudio Bog za sve narode. Sjetio se Bog naroda svoga i dosudio pravdu baštini svojoj. I bit će im – narodu njegovu Izraelu – ovi dani mjeseca adara, to jest četrnaesti i petnaesti, dani okupljanja, radosti i veselja pred Bogom za pokoljenja dovijeka.« Četvrte godine kraljevanja Ptolemejeva i Kleopatrina, Dositej, koji se kazao kao svećenik i levit, i njegov sin Ptolemej doniješe ovo pismo o Purimu, tvrdeći da je vjerodostojno i da ga je preveo Lizimah, sin Ptolemejev, iz Jeruzalema.', '', '', '{}', 0, 1, '2026-11-04T08:22:59+00:00') ON CONFLICT(id) DO UPDATE SET ref = excluded.ref, book_order = excluded.book_order, chapter = excluded.chapter, verse = excluded.verse, layer = excluded.layer, kind = excluded.kind, priority = excluded.priority, is_sample = excluded.is_sample, msg = excluded.msg, ks_text = excluded.ks_text, foi_text = excluded.foi_text, u68_text = excluded.u68_text, extra_json = excluded.extra_json, in_errata = excluded.in_errata, active = excluded.active, updated_at = excluded.updated_at;
