INSERT INTO audit_findings (id, ref, book_order, chapter, verse, layer, kind, priority, is_sample, msg, ks_text, foi_text, u68_text, extra_json, in_errata, active, updated_at) VALUES ('f894c9613593', 'Otk 10,9', 73, 10, 9, 'tipografija', 'razmak_prije_interpunkcije', 3, 0, '„…: »Uzmi je i progutaj ! Zagorčit će ti utro…”', 'Pristupim k anđelu i zamolim ga da mi dade knjižicu. A on će mi: »Uzmi je i progutaj ! Zagorčit će ti utrobu, ali će ti u ustima biti slatka kao med. «', '', '', '{}', 0, 1, '2026-11-04T08:22:59+00:00') ON CONFLICT(id) DO UPDATE SET ref = excluded.ref, book_order = excluded.book_order, chapter = excluded.chapter, verse = excluded.verse, layer = excluded.layer, kind = excluded.kind, priority = excluded.priority, is_sample = excluded.is_sample, msg = excluded.msg, ks_text = excluded.ks_text, foi_text = excluded.foi_text, u68_text = excluded.u68_text, extra_json = excluded.extra_json, in_errata = excluded.in_errata, active = excluded.active, updated_at = excluded.updated_at;
INSERT INTO audit_findings (id, ref, book_order, chapter, verse, layer, kind, priority, is_sample, msg, ks_text, foi_text, u68_text, extra_json, in_errata, active, updated_at) VALUES ('8425f0f1f78b', 'Otk 14,14', 73, 14, 14, 'tipografija', 'razmak_prije_interpunkcije', 3, 0, '„…etko kao Sin Čovječji ; na glavi mu zlatan …”', 'I vidjeh: gle, bijel oblak, a na oblak sjede Netko kao Sin Čovječji ; na glavi mu zlatan vijenac, u ruci oštar srp.', '', '', '{}', 0, 1, '2026-11-04T08:22:59+00:00') ON CONFLICT(id) DO UPDATE SET ref = excluded.ref, book_order = excluded.book_order, chapter = excluded.chapter, verse = excluded.verse, layer = excluded.layer, kind = excluded.kind, priority = excluded.priority, is_sample = excluded.is_sample, msg = excluded.msg, ks_text = excluded.ks_text, foi_text = excluded.foi_text, u68_text = excluded.u68_text, extra_json = excluded.extra_json, in_errata = excluded.in_errata, active = excluded.active, updated_at = excluded.updated_at;
